package dev.blossom.core;
import java.util.Properties;
public final class VisualSettings {
    public int hitColor=0xffd841e6,hitDuration=10;public float hitOpacity=.3f;public boolean hitFade=true,hitPlayers=true,hitMobs=true,hitArmor=true;
    public static final String[] CATEGORIES={"Critical hits","Sharpness","Normal hits","Enchantments","Block breaking","Explosions","Potions","Flame / smoke","Portals","Water","Weather","Other"};
    public final boolean[] enabled=new boolean[12];public final float[] density=new float[12],scale=new float[12],opacity=new float[12],lifetime=new float[12];public final int[] color=new int[12];
    public VisualSettings(){for(int i=0;i<12;i++){enabled[i]=true;density[i]=scale[i]=opacity[i]=lifetime[i]=1;color[i]=0xffffffff;}}
    public static int category(int id){switch(id){case 9:return 0;case 10:return 1;case 36:return 2;case 25:return 3;case 37:case 38:return 4;case 0:case 1:case 2:case 3:return 5;case 13:case 14:case 15:case 16:case 17:return 6;case 11:case 12:case 19:case 26:case 27:case 29:return 7;case 24:return 8;case 4:case 5:case 6:case 7:case 8:case 18:return 9;case 39:return 10;default:return 11;}}
    public void load(Properties p){hitColor=ClientSettings.color(p,"hit.color",0xffd841e6);hitDuration=ClientSettings.integer(p,"hit.duration",10,1,40);hitOpacity=ClientSettings.number(p,"hit.opacity",.3f,0,1);hitFade=Boolean.parseBoolean(p.getProperty("hit.fade","true"));hitPlayers=Boolean.parseBoolean(p.getProperty("hit.players","true"));hitMobs=Boolean.parseBoolean(p.getProperty("hit.mobs","true"));hitArmor=Boolean.parseBoolean(p.getProperty("hit.armor","true"));for(int i=0;i<12;i++){String k="particle."+i+".";enabled[i]=Boolean.parseBoolean(p.getProperty(k+"enabled","true"));density[i]=ClientSettings.number(p,k+"density",1,0,4);scale[i]=ClientSettings.number(p,k+"scale",1,.1f,3);opacity[i]=ClientSettings.number(p,k+"opacity",1,0,1);lifetime[i]=ClientSettings.number(p,k+"lifetime",1,.25f,3);color[i]=ClientSettings.color(p,k+"color",0xffffffff);}}
    public void save(Properties p){p.setProperty("hit.color",Integer.toHexString(hitColor));p.setProperty("hit.duration",""+hitDuration);p.setProperty("hit.opacity",""+hitOpacity);p.setProperty("hit.fade",""+hitFade);p.setProperty("hit.players",""+hitPlayers);p.setProperty("hit.mobs",""+hitMobs);p.setProperty("hit.armor",""+hitArmor);for(int i=0;i<12;i++){String k="particle."+i+".";p.setProperty(k+"enabled",""+enabled[i]);p.setProperty(k+"density",""+density[i]);p.setProperty(k+"scale",""+scale[i]);p.setProperty(k+"opacity",""+opacity[i]);p.setProperty(k+"lifetime",""+lifetime[i]);p.setProperty(k+"color",Integer.toHexString(color[i]));}}
}
